import{_ as i,l,o as e,c as s,v as r,p as n,x as t,d as A,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"ARP 欺骗","description":"","frontmatter":{"title":"ARP 欺骗","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/arp-spoofing.md","filePath":"cs/arp-spoofing.md","lastUpdated":1789023840000}'),h={name:"cs/arp-spoofing.md"};function c(P,a,E,T,_,m){const o=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="arp-欺骗" tabindex="-1">ARP 欺骗 <a class="header-anchor" href="#arp-欺骗" aria-label="Permalink to &quot;ARP 欺骗&quot;">​</a></h1><div class="epigraph"><p>以太网用 ARP 问「谁有这个 IP」。谁先答、答得勤，谁就能当网关。这是局域网的映射欺骗，不是路由协议的全球问题。</p><footer>—— 据 Plummer, RFC 826；对照 Cisco/IANA 对动态 ARP 检查一类防御</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/dns-cache-poisoning">DNS 投毒</a>在三层之上。缺口是<strong>同网段</strong>：ARP 无认证。本课收机制与交换机侧防御，不给欺骗操作步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主机把 MAC 写入 ARP 表后，帧发往攻击者网卡，再转发则成中间人。对 TLS 仍要验证书；明文 HTTP 与内部无 TLS 服务会直接泄漏。缺口是二层信任假设，不是再讲以太网帧。</p><h3 id="静态表与-dai" tabindex="-1">静态表与 DAI <a class="header-anchor" href="#静态表与-dai" aria-label="Permalink to &quot;静态表与 DAI&quot;">​</a></h3><p>关键主机可静态 ARP；交换机可做动态 ARP 检查绑定 DHCP 侦听。那是网络作业，不是密码学。</p><p><span class="marginnote">RFC 826。本课禁止 ARP 欺骗教程。无线客户端隔离是另一缓解。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>陈述：无认证的请求/应答、缓存覆盖。防御：分段、DAI、最小二层域、应用全 TLS。对照 VPN：远程用户进同一 L2 广播域会放大这条。</p>',12)),(e(),n(p,null,{default:t(()=>[d(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E8%B0%81%E6%9C%89%20IP%22%5D%20--%3E%20ANS%5B%22%E6%97%A0%E8%AE%A4%E8%AF%81%E5%BA%94%E7%AD%94%22%5D%0A%20%20ANS%20--%3E%20TAB%5B%22ARP%20%E8%A1%A8%E8%A2%AB%E5%86%99%22%5D%0A%20%20TAB%20--%3E%20MITM%5B%22%E5%B8%A7%E8%B5%B0%E5%90%91%E9%94%99%E8%AF%AF%20MAC%22%5D%0A%20%20TLS%5B%22%E5%BA%94%E7%94%A8%20TLS%20%E9%AA%8C%E5%90%8D%22%5D%20-.-%3E%7C%22%E4%BB%8D%E5%8F%AF%E6%8B%A6%E5%86%92%E5%85%85%20HTTPS%22%7C%20MITM%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>信道单元收口：从证书、无线、DNS 到 ARP，每一层都有「映射可被骗」。下一课序身份：应用如何发令牌——JWT 常把映射问题换成签名问题，然后自己关验签。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写交换机 CAM 溢出步骤。JWT 下一课：令牌合同。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DNS 骗名字；ARP 骗同网段 MAC。</li><li>无认证映射；防御在分段与检查，不在更长 AES。</li><li>应用 TLS 仍是安全带。</li><li>下一课序：JWT 陷阱。</li><li>出处：RFC 826；对照 Anderson 对链路层信任；NIST 对分段的讨论。</li></ul>',8))])}const S=i(h,[["render",c]]);export{f as __pageData,S as default};
